 let body='';
 if(translationStage===0)body=`<h3>從 NotebookLM 複製哪些內容？</h3><ol class="source-steps"><li>課名與核心問題</li><li>經核對的 3～5 個主要重點</li><li>三個教學部分的標題、概念、重點與教材例子</li><li>三部分先後關係</li><li>「教材未明確提供」與待確認處</li></ol><p>不要只貼摘要，也不要貼不必要的學生個資。</p><p><strong>回到一開始使用的 ChatGPT 對話；若已關閉，也可建立新對話。先貼上這些分析結果，再到下一步貼完整 Prompt。</strong></p><a class="secondary" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">開啟 ChatGPT ↗</a>`;
 if(translationStage===1)body=`<h3>第一次正式做教學轉譯</h3><p>確認已在 ChatGPT 貼上 NotebookLM 的分析結果，再複製下方指令、貼上並送出。先保留第一次結果，不要直接接受。</p><h4>第一次完整 Prompt（ChatGPT）</h4><button id="copy-prompt" class="primary">複製 Prompt</button><span id="prompt-status" role="status"></span><pre id="prompt-preview" class="prompt-box">${escapeHTML(buildPrompt(5))}</pre>`;
 if(translationStage===2)body=`<h3>先閱讀，不要直接接受</h3><p>把 ChatGPT 第一次結果與原教材放在一起看，檢查這五件事：</p><ul class="translation-checks"><li>教材內容有沒有改錯？</li><li>難度適不適合這個年級？</li><li>三個部分與先後關係有沒有保留？</li><li>有沒有增加教材沒有的內容？</li><li>學生看得懂嗎？</li></ul><p><strong>挑一個不滿意的地方，下一步請 ChatGPT 改一次。</strong></p>`;
 if(translationStage===3)body=`<h3>至少追問一次，再比較</h3><p>選一個最符合你看到的問題。前兩種請填入要修改的原句；也可以自行改寫指令。</p><div class="followup-options">${TRANSLATE_FOLLOWUPS.map((f,n)=>`<button type="button" class="secondary" data-followup="${n}" aria-pressed="${Number(existing.followupChoice||0)===n}">${f.title}</button>`).join('')}</div><label class="field"><span>追問內容（可修改）</span><textarea id="followup-text" maxlength="12000">${escapeHTML(existing.followupText||TRANSLATE_FOLLOWUPS[Math.max(0,Math.min(2,Number(existing.followupChoice)||0))].prompt.replace('【年級】',effectiveContent(1).grade))}</textarea></label><button id="copy-followup" class="primary">複製追問</button><span id="prompt-status" role="status"></span><p>貼回 ChatGPT，送出後保留第二次結果。</p><div class="goal-pair"><div class="flow-card"><h4>比較第一次與第二次</h4><p>問題修好了嗎？有沒有改掉原本正確的內容？</p></div><div class="flow-card"><h4>老師決定最後版本</h4><p>選擇要保留的說法，再讀一次「需要老師確認」清單。</p></div></div><button id="record-translation" class="primary">記錄已轉譯、追問並比較</button><p id="translation-status" role="status">只在實際完成後記錄；這不是系統自動驗證。</p>`;
 $('activity').innerHTML=`<div class="activity-card"><div class="activity-meta"><span class="activity-number">活動 06</span><span>循環 3 · 做出與試用</span></div><h2>ChatGPT 教學轉譯</h2><p>不改變知識，改成學生容易理解的語言。</p><div class="tool-stages"><strong>ChatGPT ● 使用中｜教學轉譯</strong><span>NotebookLM ✓ 分析已完成</span><span>Codex ○ 版本 B 使用</span></div><nav class="translation-tabs" aria-label="第六關小步驟">${labels.map((label,n)=>`<button data-translation-stage="${n}" class="secondary" ${n===translationStage?'aria-current="step"':''}>${String(n+1).padStart(2,'0')} ${label}</button>`).join('')}</nav><section class="translation-panel" aria-labelledby="translation-stage-title"><p class="eyebrow" id="translation-stage-title">步驟 ${translationStage+1} / 4 · ${labels[translationStage]}</p>${body}</section><div class="demo-actions"><button id="translation-prev" class="secondary" ${translationStage===0?'disabled':''}>← 上一步</button><button id="translation-next" class="primary" ${translationStage===3?'hidden':''}>下一小步 →</button></div><div id="artifact-preview" hidden>${escapeHTML(WORKSHOP_DEMOS[5].artifact)}</div></div>`;
 function stash(extra){const c={...effectiveContent(5),...existing,...extra};recordContent(5,'custom',c);renderNav();}
 $('activity').querySelectorAll('[data-translation-stage]').forEach(b=>b.addEventListener('click',()=>{translationStage=Number(b.dataset.translationStage);renderTranslation();}));
 $('translation-prev').addEventListener('click',()=>{translationStage=Math.max(0,translationStage-1);renderTranslation();});
