 $('activity').querySelectorAll('[data-followup]').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.followup);stash({followupChoice:String(n),followupText:TRANSLATE_FOLLOWUPS[n].prompt.replace('【年級】',effectiveContent(1).grade)});renderTranslation();}));
 $('followup-text')?.addEventListener('input',e=>stash({followupText:e.target.value}));
